function m(n,t={}){if(n==null||Number.isNaN(n))return"—";const s=Math.round(n),i=Math.abs(s).toLocaleString("en-US");return`⁦${s<0?"−":t.signed&&s>0?"+":""}${i} ₪⁩`}function a(n,t,s={}){if(n==null||Number.isNaN(n))return"—";const i=t==="USD",r=Math.abs(n),o=i?r.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2}):Math.round(r).toLocaleString("en-US");return`⁦${n<0?"−":s.signed&&n>0?"+":""}${o} ${i?"$":"₪"}⁩`}function u(n,t=1){return n==null||Number.isNaN(n)?"—":n.toFixed(t)+"%"}function f(n){if(!n)return"—";const t=/^(\d{4})-(\d{2})-(\d{2})/.exec(n);return t?`${t[3]}/${t[2]}/${t[1]}`:n}export{f as a,a as b,u as c,m as f};
